import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import fs from 'fs';
import { createScene } from './data/object.js';

// Create the scene
const root = createScene();

// Apply -90 degree X-rotation for Blender Z-up space
const rotationMatrix = new THREE.Matrix4();
rotationMatrix.makeRotationX(-Math.PI / 2);

// Update all world matrices
root.updateMatrixWorld(true);

// Collect all geometries with world transforms
const geometries = [];

root.traverse((obj) => {
  if (obj instanceof THREE.Mesh) {
    // Clone the geometry
    const geom = obj.geometry.clone();

    // Apply the mesh's world matrix to get world coordinates
    geom.applyMatrix4(obj.matrixWorld);

    // Apply the Blender rotation transform
    geom.applyMatrix4(rotationMatrix);

    geometries.push(geom);
  } else if (obj instanceof THREE.InstancedMesh) {
    // Handle instanced meshes
    const geom = obj.geometry.clone();

    for (let i = 0; i < obj.count; i++) {
      const matrix = new THREE.Matrix4();
      obj.getMatrixAt(i, matrix);

      // Combine instance matrix with parent's world matrix
      const combinedMatrix = new THREE.Matrix4();
      combinedMatrix.multiplyMatrices(obj.matrixWorld, matrix);

      // Apply Blender rotation
      combinedMatrix.multiplyMatrices(rotationMatrix, combinedMatrix);

      // Clone geometry for this instance
      const instanceGeom = geom.clone();
      instanceGeom.applyMatrix4(combinedMatrix);

      geometries.push(instanceGeom);
    }
  }
});

// Merge all geometries
let mergedGeometry;
if (geometries.length > 0) {
  mergedGeometry = mergeGeometries(geometries);
} else {
  console.error('No geometries found in scene!');
  process.exit(1);
}

// Create a mesh with merged geometry
const exportMesh = new THREE.Mesh(mergedGeometry);

// Export to OBJ
const exporter = new OBJExporter();
const objString = exporter.parse(exportMesh);

// Ensure output directory exists
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Write to file
const outputPath = '/root/output/object.obj';
fs.writeFileSync(outputPath, objString);

console.log(`✓ Successfully exported to ${outputPath}`);
console.log(`  Geometries merged: ${geometries.length}`);
console.log(`  Vertices: ${mergedGeometry.attributes.position.count}`);
console.log(`  Applied -90° X-rotation for Blender Z-up coordinate system`);

